        if bv != av:
            changes.append((proj, pkg, bv or 'N/A', av or 'N/A'))
        else:
            unchanged.append((proj, pkg, bv))

print('=== CHANGES ===')
for c in changes: print(f'  {c[0]:20s} {c[1]:40s} {c[2]:>10s} -> {c[3]}')
print(f'\\n=== UNCHANGED ({len(unchanged)} entries) ===')
for u in unchanged: print(f'  {u[0]:20s} {u[1]:40s} {u[2]:>10s}')
"

