import sys, json

# dotnet list package with slnx outputs multiple JSON objects concatenated
text = sys.stdin.read()
# Try parsing as single JSON first
try:
    data = json.load(json.JSONDecoder().raw_decode(text))
except:
    pass

# Parse all JSON objects
decoder = json.JSONDecoder()
idx = 0
projects = []
while idx < len(text):
    text_part = text[idx:].lstrip()
    if not text_part:
        break
    idx = len(text) - len(text_part)
    try:
        obj, end = decoder.raw_decode(text, idx)
        projects.extend(obj.get('projects', []))
        idx += end
    except json.JSONDecodeError:
        idx += 1

for p in projects:
    name = p['path'].split('/')[-1]
    for fw in p.get('frameworks', []):
        for pkg in fw.get('topLevelPackages', []):
            print(f'{name:20s} {pkg[\"id\"]:40s} {pkg[\"resolvedVersion\"]}')
"

